seq = []
with open("region.fasta") as f:
    for line in f:
        line = line.strip()
        if not line.startswith(">"):
            seq.append(line)
s = "".join(seq).upper()

def revcomp(x):
    return x.translate(str.maketrans("ACGT","TGCA"))[::-1]

starts = set(["ATG"])
stops = set(["TAA","TAG","TGA"])

def find_orfs(s):
    orfs = []
    L = len(s)
    for frame in range(3):
        i = frame
        while i < L-2:
            codon = s[i:i+3]
            if codon in starts:
                # scan forward
                j = i
                ok = None
                while j < L-2:
                    c2 = s[j:j+3]
                    if c2 in stops:
                        ok = j+2
                        break
                    j += 3
                if ok:
                    orfs.append((frame+1, i+1, ok+1, (ok-i+3)//3, s[i:i+3]))  # 1-based coords frame, start,end, aalen, startcodon
                i = (i if ok is None else ok+1)+3  # after stop
                if ok is None: break
            else:
                i += 3
    return orfs

orfs_f = find_orfs(s)
orfs_r = find_orfs(revcomp(s))

print("Forward-frame ORFs (ATG...stop), sorted by aa length:")
for o in sorted(orfs_f, key=lambda x:-x[3])[:15]:
    print(f"  frame {o[0]}, {o[1]}-{o[2]} len {o[3]} aa, start codon {o[4]}")
print()
print("Reverse-frame ORFs (on reverse complement), top by aa length:")
for o in sorted(orfs_r, key=lambda x:-x[3])[:15]:
    print(f"  frame {o[0]}, {o[1]}-{o[2]} rc len {o[3]} aa, start codon {o[4]}")
